# -*- coding: utf-8 -*-
"""add_modern_places.py — Bổ sung các địa điểm nổi tiếng / hiện đại còn thiếu vào DB.

Cách dùng: python3 tools/add_modern_places.py
- Mỗi mục trong CANDIDATES sẽ được thêm vào data/regions/<region>.json nếu slug CHƯA có.
- Nội dung tiếng Việt là nguyên gốc (tự soạn), rating để trống nếu chưa có nguồn xác thực.
- Đây là "khung" để mở rộng dần: chỉ cần thêm mục mới vào CANDIDATES.
"""
import json, os, glob, urllib.parse, datetime

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)
REGIONS = os.path.join(ROOT, "data", "regions")
QUEUE = os.path.join(ROOT, "_source", "regions_queue.json")
try:
    TODAY = datetime.date.today().isoformat()
except Exception:
    TODAY = "2026-07-23"

RMETA = {}
if os.path.exists(QUEUE):
    for r in json.load(open(QUEUE, encoding="utf-8")).get("regions", []):
        RMETA[r["slug"]] = (r.get("name_vi", r["slug"]), r.get("federal_district", ""))


def maps(lat, lon):
    return {"yandex": f"https://yandex.com/maps/?pt={lon},{lat}&z=16&l=map",
            "google": f"https://www.google.com/maps/search/?api=1&query={lat},{lon}"}


def wiki(name_en):
    return [{"title": "Wikipedia (EN)", "url": "https://en.wikipedia.org/wiki/Special:Search?search=" + urllib.parse.quote(name_en)}]


def rec(region, slug, name_vi, name_ru, name_en, cats, lat, lon, addr, short, long, hl, tags, practical=None, sources=None, status="enriched", official_site=None):
    nv, fed = RMETA.get(region, (region, ""))
    return {
        "id": f"{region}-{slug}", "slug": slug, "region": region,
        "region_name_vi": nv, "federal_district": fed,
        "name_vi": name_vi, "name_ru": name_ru, "name_en": name_en,
        "categories": cats, "coordinates": {"lat": lat, "lon": lon}, "address_vi": addr,
        "rating": {"value": None, "count": None, "source": None, "as_of": None},
        "review_summary_vi": "",
        "presentation_short_vi": short, "presentation_long_vi": long,
        "highlights_vi": hl, "practical": practical or {},
        "photo": None, "photo_credit": None,
        "maps": maps(lat, lon), "official_site": official_site,
        "sources": sources or wiki(name_en), "tags": tags, "status": status, "last_updated": TODAY,
    }


